using System;
using System.Collections.Generic;

namespace Cnidaria.RiscV
{
    /// <summary>The whole instruction set, generated from the riscv-opcodes tables</summary>
    internal static class RVEncodedInstructions
    {
        internal readonly struct Entry
        {
            public Entry(RVInstrKind opcode, string mnemonic, uint match, uint mask, RVIsaFlags requiredIsa, bool requires64Bit, string pattern, bool compressed, bool requires32Bit = false)
            {
                Opcode = opcode;
                Mnemonic = mnemonic;
                RequiredIsa = requiredIsa;
                Requires64Bit = requires64Bit;
                Requires32Bit = requires32Bit;
                Form = RVEncodedForm.Create(match, mask, pattern, compressed);
            }

            public RVInstrKind Opcode { get; }
            public string Mnemonic { get; }
            public RVIsaFlags RequiredIsa { get; }
            public bool Requires64Bit { get; }
            public bool Requires32Bit { get; }
            public RVEncodedForm Form { get; }
        }

        private static readonly Entry[] Entries = Create();
        private static readonly Dictionary<RVInstrKind, string> Mnemonics = BuildMnemonics();

        public static IReadOnlyList<Entry> All => Entries;

        public static bool TryGetMnemonic(RVInstrKind opcode, out string mnemonic)
            => Mnemonics.TryGetValue(opcode, out mnemonic!);

        private static readonly Dictionary<string, RVInstrKind> Opcodes = BuildOpcodes();

        /// <summary>Finds the instruction a mnemonic names, which is how a name-driven caller reaches one</summary>
        public static bool TryGetOpcode(string mnemonic, out RVInstrKind opcode)
            => Opcodes.TryGetValue(mnemonic, out opcode);

        private static Dictionary<string, RVInstrKind> BuildOpcodes()
        {
            var map = new Dictionary<string, RVInstrKind>(StringComparer.Ordinal);
            foreach (var entry in Entries)
                map[entry.Mnemonic] = entry.Opcode;
            return map;
        }

        private static Dictionary<RVInstrKind, string> BuildMnemonics()
        {
            var map = new Dictionary<RVInstrKind, string>();
            foreach (var entry in Entries)
                map[entry.Opcode] = entry.Mnemonic;
            return map;
        }

